package com.hbm.client.radar;
import com.hbm.machine.radar.*;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.fml.event.lifecycle.FMLClientSetupEvent;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.client.extensions.common.*;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD) public final class RadarClient{@SubscribeEvent public static void setup(FMLClientSetupEvent event){event.enqueueWork(()->{RadarBlockEntity.OPEN=pos->{var mc=Minecraft.getInstance();if(mc.level!=null&&mc.level.getBlockEntity(pos) instanceof RadarBlockEntity radar)mc.setScreen(new RadarScreen(radar));};RadarStatePacket.CLIENT=packet->{var mc=Minecraft.getInstance();if(mc.level!=null&&mc.level.getBlockEntity(packet.position()) instanceof RadarBlockEntity radar){radar.power=packet.power();radar.clientMaxPower=packet.maxPower();radar.clientRange=packet.range();radar.clientConsumption=packet.consumption();int f=packet.flags();radar.scanMissiles=(f&1)!=0;radar.scanShells=(f&2)!=0;radar.scanPlayers=(f&4)!=0;radar.smartMode=(f&8)!=0;radar.redMode=(f&16)!=0;radar.showMap=(f&32)!=0;radar.jammed=(f&64)!=0;radar.entries.clear();radar.entries.addAll(packet.entries());if((f&128)!=0||radar.map==null||radar.map.length!=40000)radar.map=new byte[40000];else if(packet.mapIndex()>=0&&packet.mapIndex()<400)System.arraycopy(packet.map(),0,radar.map,packet.mapIndex()*100,100);}};});}@SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers e){e.registerBlockEntityRenderer(RadarContent.ENTITY.get(),RadarRenderer::new);e.registerBlockEntityRenderer(RadarContent.LARGE_ENTITY.get(),RadarRenderer::new);e.registerBlockEntityRenderer(RadarContent.SCREEN_ENTITY.get(),RadarDisplayRenderer::new);}@SubscribeEvent public static void screens(RegisterMenuScreensEvent e){e.register(RadarContent.MENU.get(),RadarInventoryScreen::new);}@SubscribeEvent public static void extensions(RegisterClientExtensionsEvent e){for(int i=0;i<3;i++){final int kind=i;var item=i==0?RadarContent.ITEM:i==1?RadarContent.LARGE_ITEM:RadarContent.SCREEN_ITEM;e.registerItem(new IClientItemExtensions(){private RadarItemRenderer renderer;@Override public BlockEntityWithoutLevelRenderer getCustomRenderer(){if(renderer==null)renderer=new RadarItemRenderer(kind);return renderer;}},item.get());}}private RadarClient(){}}
